"""Exact homology relative to the submodule generated by the included horn faces."""

import argparse

import numpy as np

from simplicial_tensors.homology import relative_horn_homology


def key_tensor(tensor):
    """Key a tensor by its shape and ordered entries."""
    array = np.asarray(tensor, dtype=object)
    return array.shape, tuple(array.flat)


def relative_homology_dimension(shape, j, *, seed=123, modulus=None, tensor=None):
    """Return the top relative Betti number for a tensor of the given shape.

    If tensor is omitted, draw entries uniformly from -5,...,5 with the
    supplied seed. The quotient is by the simplicial submodule generated
    by d_i(tensor) for i != j. All ranks are exact over Q or F_p.
    """
    shape = tuple(shape)
    if tensor is None:
        tensor = np.random.default_rng(seed).integers(-5, 6, size=shape)
    elif np.shape(tensor) != shape:
        raise ValueError("The supplied tensor must have the stated shape.")
    result = relative_horn_homology(tensor, j, modulus=modulus)
    degree = min(shape) - 1
    return result.homology_dimensions[degree] if degree < len(result.homology_dimensions) else 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--seed", type=int, default=123)
    parser.add_argument("--modulus", type=int, help="Prime coefficient modulus; default Q")
    args = parser.parse_args()
    print(f"seed={args.seed}, coefficient field="
          f"{'Q' if args.modulus is None else f'F_{args.modulus}'}")
    for shape in [(3, 3), (4, 4), (2, 2, 2), (3, 3, 3)]:
        tensor = np.random.default_rng(args.seed).integers(-5, 6, size=shape)
        for omitted in range(min(shape)):
            result = relative_horn_homology(tensor, omitted, modulus=args.modulus)
            print(f"shape={shape}, omitted face={omitted}, "
                  f"normalized dimensions={result.chain_dimensions}, "
                  f"boundary ranks={result.boundary_ranks}, "
                  f"relative Betti numbers={result.homology_dimensions}")


if __name__ == "__main__":
    main()
